catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }

	g_form.clearOptions('injury_location');

	if (g_lang == "en"){
		g_form.addOption('injury_location', '', 'Please select..');

		if (newValue == 'Toes') {
			g_form.addOption('injury_location', 'Left foot', 'Left foot');
			g_form.addOption('injury_location', 'Right foot', 'Right foot');
			g_form.addOption('injury_location', 'Both foot', 'Both feet');
			return;
		}

		if (newValue == 'Fingers') {
			g_form.addOption('injury_location', 'Left hand', 'Left hand');
			g_form.addOption('injury_location', 'Right hand', 'Right hand');
			g_form.addOption('injury_location', 'Both hand', 'Both hands');
			return;
		}

		g_form.addOption('injury_location', 'Left', 'Left');
		g_form.addOption('injury_location', 'Right', 'Right');
		g_form.addOption('injury_location', 'Both', 'Both');
	}

	if (g_lang == "fq"){
		g_form.addOption('injury_location', '', 'Veuillez sélectionner..');

		if (newValue == 'Orteils') {
			g_form.addOption('injury_location', 'Pied gauche', 'Pied gauche');
			g_form.addOption('injury_location', 'Pied droit', 'Pied droit');
			g_form.addOption('injury_location', 'Les deux pieds', 'Les deux pieds');
			return;
		}

		if (newValue == 'Doigts') {
			g_form.addOption('injury_location', 'Main gauche', 'Main gauche');
			g_form.addOption('injury_location', 'Main droite', 'Main droite');
			g_form.addOption('injury_location', 'Les deux mains', 'Les deux mains');
			return;
		}

		g_form.addOption('injury_location', 'Gauche', 'Gauche');
		g_form.addOption('injury_location', 'Droite', 'Droite');
		g_form.addOption('injury_location', 'Tous les deux', 'Tous les deux');
	}

}
